<div class="wrap wcad-wrap"><div class="wcad-heading"><div><p class="wcad-eyebrow">WOOCOMMERCE / ANALYTICS</p><h1><?php esc_html_e( 'WCAD Settings', 'woocommerce-analytics-dashboard' ); ?></h1><p class="wcad-muted">Dashboard preferences</p></div></div><div class="wcad-card wcad-settings-card"><form action="options.php" method="post"><?php settings_fields( 'wcad_settings' ); ?><label for="wcad_default_range"><strong>Default date range</strong></label><p class="wcad-muted">Choose the initial period when opening the dashboard.</p><select id="wcad_default_range" name="wcad_default_range"><?php foreach ( array( 7, 30, 90 ) as $days ) : ?><option value="<?php echo esc_attr( (string) $days ); ?>" <?php selected( (int) get_option( 'wcad_default_range', 30 ), $days ); ?>><?php echo esc_html( sprintf( '%d days', $days ) ); ?></option><?php endforeach; ?></select><?php submit_button(); ?></form></div></div>
